import { apiRequest, SkillplaneApiError } from "$lib/api/client.js";
import { withWorkspaceDatafnClient } from "$lib/datafn/client.js";
import type {
  AmendmentPolicyDecision,
  CallerDeclaration,
  LearningMetadata,
  SemanticBump,
  Skill,
  SkillArchiveFilter,
  SkillBundleManifest,
  SkillPage,
  SkillVersion,
  SkillVersionStatus,
  SkillVisibility,
} from "./types.js";

type DatafnRecord = Readonly<Record<string, unknown>>;

function requiredString(row: DatafnRecord, field: string): string {
  const value = row[field];
  if (typeof value !== "string") {
    throw new Error(`DataFn returned an invalid ${field} field`);
  }
  return value;
}

function optionalString(row: DatafnRecord, field: string): string | null {
  const value = row[field];
  if (value === null || value === undefined) return null;
  if (typeof value !== "string") {
    throw new Error(`DataFn returned an invalid ${field} field`);
  }
  return value;
}

function dateString(row: DatafnRecord, field: string): string {
  const value = row[field];
  if (value instanceof Date) return value.toISOString();
  if (typeof value === "string" && Number.isFinite(Date.parse(value))) {
    return new Date(value).toISOString();
  }
  throw new Error(`DataFn returned an invalid ${field} field`);
}

function optionalDateString(row: DatafnRecord, field: string): string | null {
  return row[field] === null || row[field] === undefined
    ? null
    : dateString(row, field);
}

function recordValue(row: DatafnRecord, field: string): Record<string, unknown> {
  const value = row[field];
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function arrayValue(row: DatafnRecord, field: string): readonly unknown[] {
  const value = row[field];
  return Array.isArray(value) ? value : [];
}

function skillFromDatafn(row: DatafnRecord, workspaceId: string): Skill {
  const currentVersion = row.currentVersion;
  const currentSemanticVersion =
    currentVersion &&
    typeof currentVersion === "object" &&
    !Array.isArray(currentVersion)
      ? optionalString(currentVersion as DatafnRecord, "semanticVersion")
      : null;
  return {
    id: requiredString(row, "id"),
    workspaceId,
    slug: requiredString(row, "slug"),
    name: requiredString(row, "name"),
    description: requiredString(row, "description"),
    tags: arrayValue(row, "tags").filter(
      (tag): tag is string => typeof tag === "string",
    ),
    visibility: requiredString(row, "visibility") as SkillVisibility,
    currentPublishedVersionId: optionalString(row, "currentPublishedVersionId"),
    currentSemanticVersion,
    archivedAt: optionalDateString(row, "archivedAt"),
    createdAt: dateString(row, "createdAt"),
    updatedAt: dateString(row, "updatedAt"),
  };
}

function skillVersionFromDatafn(row: DatafnRecord, workspaceId: string): SkillVersion {
  const revision = row.revision;
  const byteSize = row.bundleByteSize;
  if (typeof revision !== "number" || typeof byteSize !== "number") {
    throw new Error("DataFn returned invalid skill version metadata");
  }
  return {
    id: requiredString(row, "id"),
    workspaceId,
    skillId: requiredString(row, "skillId"),
    revision,
    semanticVersion: optionalString(row, "semanticVersion"),
    status: requiredString(row, "status") as SkillVersionStatus,
    baseVersionId: optionalString(row, "baseVersionId"),
    proposedBump: optionalString(row, "proposedBump") as SemanticBump | null,
    source: requiredString(row, "source") as SkillVersion["source"],
    digest: requiredString(row, "contentDigest") as `sha256:${string}`,
    byteSize,
    manifest: recordValue(row, "manifest") as unknown as SkillBundleManifest,
    learningMetadata: recordValue(row, "learningMetadata") as
      LearningMetadata | Readonly<Record<string, never>>,
    amendmentOperations: arrayValue(
      row,
      "amendmentOperations",
    ) as SkillVersion["amendmentOperations"],
    callerDeclaration: recordValue(row, "callerDeclaration") as
      CallerDeclaration | Readonly<Record<string, never>>,
    policyDecision: recordValue(row, "policyDecision") as
      AmendmentPolicyDecision | Readonly<Record<string, never>>,
    changeSummary: requiredString(row, "changeSummary"),
    createdByActorType: requiredString(
      row,
      "createdByActorType",
    ) as SkillVersion["createdByActorType"],
    createdByActorId: requiredString(row, "createdByActorId"),
    createdByAgent: optionalString(row, "createdByAgent"),
    createdByModel: optionalString(row, "createdByModel"),
    createdForUserId: optionalString(row, "createdForUserId"),
    publishedAt: optionalDateString(row, "publishedAt"),
    createdAt: dateString(row, "createdAt"),
  };
}

function archiveFilters(archive: SkillArchiveFilter): Record<string, unknown> {
  if (archive === "active") return { archivedAt: { is_null: true } };
  if (archive === "archived") return { archivedAt: { is_not_null: true } };
  return {};
}

function encodeCursor(cursor: unknown, scope: string): string | null {
  if (!cursor) return null;
  const bytes = new TextEncoder().encode(
    JSON.stringify({ version: 1, scope, boundary: cursor }),
  );
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/u, "");
}

function cursorError(code = "CURSOR_INVALID"): SkillplaneApiError {
  return new SkillplaneApiError(400, {
    code,
    message:
      code === "CURSOR_FILTER_MISMATCH"
        ? "Skill cursor filters do not match"
        : "Skill cursor is invalid",
    requestId: "",
  });
}

function decodeCursor(cursor: string, scope: string): unknown {
  let value: unknown;
  try {
    const base64 = cursor.replaceAll("-", "+").replaceAll("_", "/");
    const binary = atob(base64.padEnd(Math.ceil(base64.length / 4) * 4, "="));
    value = JSON.parse(
      new TextDecoder().decode(
        Uint8Array.from(binary, (character) => character.codePointAt(0) ?? 0),
      ),
    );
  } catch {
    throw cursorError();
  }
  if (!value || typeof value !== "object" || Array.isArray(value)) throw cursorError();
  const record = value as Record<string, unknown>;
  if (record.version !== 1 || typeof record.scope !== "string" || !record.boundary)
    throw cursorError();
  if (record.scope !== scope) throw cursorError("CURSOR_FILTER_MISMATCH");
  return record.boundary;
}

function datafnBoundary(value: unknown): {
  readonly after?: Record<string, unknown>;
  readonly before?: Record<string, unknown>;
} {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw cursorError();
  const record = value as Record<string, unknown>;
  const key = record.after !== undefined ? "after" : "before";
  const boundary = record[key];
  if (
    !boundary ||
    typeof boundary !== "object" ||
    Array.isArray(boundary) ||
    (record.after !== undefined && record.before !== undefined)
  )
    throw cursorError();
  return { [key]: boundary as Record<string, unknown> };
}

function notFound(): SkillplaneApiError {
  return new SkillplaneApiError(404, {
    code: "SKILL_NOT_FOUND",
    message: "Skill was not found",
    requestId: "",
  });
}

export async function listSkillsWithDatafn(options: {
  readonly workspaceId: string;
  readonly query?: string;
  readonly visibility?: readonly SkillVisibility[];
  readonly archive?: SkillArchiveFilter;
  readonly cursor?: string | null;
  readonly limit?: number;
}): Promise<SkillPage> {
  const query = options.query?.trim().replace(/\s+/g, " ") ?? "";
  const archive = options.archive ?? "active";
  const visibility = [...new Set(options.visibility ?? [])].sort((left, right) =>
    left.localeCompare(right),
  );
  const scope = JSON.stringify({
    workspaceId: options.workspaceId,
    query,
    archive,
    visibility,
  });
  const boundary = options.cursor ? decodeCursor(options.cursor, scope) : undefined;
import { authfn } from "authfn";
import {
  createDatabaseClient,
  migrateDatabase,
  resolveTestDatabaseUrl,
} from "@skillplane/db";
import {
  purgeTenantFixture,
  seedTenantFixture,
  type TenantFixture,
} from "@skillplane/testing";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { createSkillplaneDatafnServer } from "../../src/server.js";

describe.each(["combined", "regional"] as const)(
  "DataFn %s database adapter",
  (role) => {
    // Dedicated tenant-A skill whose published version carries a non-empty
    // nested manifest array and date columns, used to prove relation projection
    // preserves nested arrays and Date values instead of reducing them to `{}`.
    const nestedSkillId = "skill:datafn-a-nested";
    const nestedVersionId = "skill-version:datafn-a-nested";
    const nestedManifestFiles = [
      { path: "SKILL.md", sha256: "a".repeat(64), byteSize: 1 },
      { path: "skill.json", sha256: "b".repeat(64), byteSize: 1 },
    ];
    let databaseUrl: string;
    let tenantA: TenantFixture;
    let tenantB: TenantFixture;
    let close: () => Promise<void>;
    let handle: (request: Request) => Promise<Response>;

    beforeAll(async () => {
      databaseUrl = await resolveTestDatabaseUrl();
      await migrateDatabase(databaseUrl);
      await purgeTenantFixture(databaseUrl, "datafn-a");
      await purgeTenantFixture(databaseUrl, "datafn-b");
      tenantA = await seedTenantFixture(databaseUrl, "datafn-a");
      tenantB = await seedTenantFixture(databaseUrl, "datafn-b");
      const controlDatabase = createDatabaseClient({
        connectionString: databaseUrl,
        role: "control",
      });
      const database = createDatabaseClient({ connectionString: databaseUrl, role });
      // Keep revision 1 published while adding a newer draft to exercise history order.
      await database.pool.query(
        `INSERT INTO skill_versions
           (id, workspace_id, skill_id, revision, base_version_id, status, source, content_digest,
            r2_object_key, bundle_byte_size, manifest, change_summary,
            created_by_actor_type, created_by_actor_id)
         SELECT $1, workspace_id, skill_id, 2, id, 'draft', source, content_digest,
                r2_object_key, bundle_byte_size, manifest, 'History ordering fixture',
                created_by_actor_type, created_by_actor_id
           FROM skill_versions WHERE skill_id = $2 AND revision = 1`,
        [`skill-version:datafn-a-revision-2`, tenantA.skillId],
      );
      await database.pool.query(`UPDATE skills SET next_revision = 3 WHERE id = $1`, [
        tenantA.skillId,
      ]);
      const nestedDigest = `sha256:${"a".repeat(64)}`;
      await database.pool.query(
        `INSERT INTO skills
           (id, workspace_id, slug, name, description, tags, created_by_user_id)
         VALUES ($1, $2, $3, $4, $5, $6, $7)`,
        [
          nestedSkillId,
          tenantA.workspaceId,
          "nested-datafn-a",
          "Nested DataFn A",
          "Nested relation projection fixture",
          ["review", "nested"],
          tenantA.userId,
        ],
      );
      await database.pool.query(
        `INSERT INTO skill_versions
           (id, workspace_id, skill_id, revision, semantic_version, status,
            source, content_digest, r2_object_key, bundle_byte_size, manifest,
            change_summary, created_by_actor_type, created_by_actor_id, published_at)
         VALUES (
           $1, $2, $3, 1, '1.0.0', 'published', 'import', $4, $5, 2,
           $6, 'Nested manifest fixture', 'system', $7, now()
         )`,
        [
          nestedVersionId,
          tenantA.workspaceId,
          nestedSkillId,
          nestedDigest,
          `workspaces/${tenantA.workspaceId}/skills/${nestedSkillId}/bundles/sha256/${"a".repeat(
            64,
          )}.zip`,
          {
            formatVersion: 1,
            digest: nestedDigest,
            byteSize: 2,
            expandedByteSize: 4,
            fileCount: nestedManifestFiles.length,
            files: nestedManifestFiles,
          },
          "fixture:datafn-a-nested",
        ],
      );
      await database.pool.query(
        `UPDATE skills
            SET current_published_version_id = $2, next_revision = 2
          WHERE id = $1`,
        [nestedSkillId, nestedVersionId],
      );
      const auth = authfn({
        plugins: [],
        namespace: "authfn",
        basePath: "/auth",
      }).createServer({ database: controlDatabase.adapter });
      const server = await createSkillplaneDatafnServer({
        database,
        controlDatabase,
        auth: auth.provider,
      });
      handle = (request) => server.router.handle(request);
      close = async () => {
        await server.close();
        await database.close();
        await controlDatabase.close();
      };
    });

    afterAll(async () => {
      if (close) await close();
      await purgeTenantFixture(databaseUrl, "datafn-a");
      await purgeTenantFixture(databaseUrl, "datafn-b");
    });

    function request(tenant: TenantFixture, path: string, body?: unknown): Request {
      return new Request(`http://localhost${path}`, {
        method: body === undefined ? "GET" : "POST",
        headers: {
          authorization: `Bearer ${tenant.sessionToken}`,
          "content-type": "application/json",
          "x-skillplane-workspace-id": tenant.workspaceId,
        },
        ...(body === undefined ? {} : { body: JSON.stringify(body) }),
      });
    }

    describe("DataFn tenant read model", () => {
      it("returns only rows from the authenticated workspace", async () => {
        const response = await handle(
          request(tenantA, "/datafn/query", {
            resource: "skills",
            version: 1,
            select: ["id", "name", "description"],
            limit: 20,
          }),
        );
        expect(response.status).toBe(200);
        const serialized = JSON.stringify(await response.json());
        expect(serialized).toContain(tenantA.skillId);
        expect(serialized).not.toContain(tenantB.skillId);
      });

      it("expands current skill version metadata in one tenant-filtered query", async () => {
        const response = await handle(
          request(tenantA, "/datafn/query", {
            resource: "skills",
            version: 1,
            select: ["*", "currentVersion.*"],
            filters: { id: tenantA.skillId },
            limit: 1,
          }),
        );

        expect(response.status).toBe(200);
        const payload = await response.json();
        expect(payload).toMatchObject({
          ok: true,
          result: {
            data: [
              {
                id: tenantA.skillId,
                currentVersion: {
                  semanticVersion: "1.0.0",
                  bundleByteSize: 1,
                },
              },
            ],
          },
        });
        expect(payload.result.data[0].createdAt).toMatch(/^\d{4}-\d{2}-\d{2}T/u);
        expect(payload.result.data[0].currentVersion.createdAt).toMatch(
          /^\d{4}-\d{2}-\d{2}T/u,
        );
      });

      it("preserves nested relation dates and arrays when expanding currentVersion", async () => {
        const response = await handle(
          request(tenantA, "/datafn/query", {
            resource: "skills",
            version: 1,
            select: ["id", "tags", "currentVersion.*"],
            filters: { id: nestedSkillId },
            limit: 1,
          }),
        );
        expect(response.status).toBe(200);
        const skill = (await response.json()).result.data[0];
        expect(skill.id).toBe(nestedSkillId);
        // Top-level array survives relation projection.
        expect(skill.tags).toEqual(["review", "nested"]);
        const version = skill.currentVersion;
        // Nested relation Date columns serialize as ISO strings, not `{}`.
        expect(version.createdAt).toMatch(/^\d{4}-\d{2}-\d{2}T/u);
        expect(version.publishedAt).toMatch(/^\d{4}-\d{2}-\d{2}T/u);
        // Nested arrays inside the expanded relation survive omission handling.
        expect(version.manifest.formatVersion).toBe(1);
        expect(version.manifest.files).toEqual(nestedManifestFiles);
      });

      it("reads descending version history through the domain model name with tenant isolation", async () => {
        const response = await handle(
          request(tenantA, "/datafn/query", {
            resource: "skillVersions",
            version: 1,
            select: ["*"],
            filters: { skillId: tenantA.skillId },
            sort: ["-revision"],
            limit: 100,
          }),
        );
        expect(response.status).toBe(200);
        const payload = await response.json();
        expect(
          payload.result.data.map((version: { revision: number }) => version.revision),
        ).toEqual([2, 1]);
        expect(payload.result.data).toMatchObject([
          { skillId: tenantA.skillId, revision: 2, status: "draft" },
          { skillId: tenantA.skillId, revision: 1, semanticVersion: "1.0.0" },
        ]);
        for (const version of payload.result.data) {
          expect(version.createdAt).toMatch(/^\d{4}-\d{2}-\d{2}T/u);
        }
        const foreign = await handle(
          request(tenantA, "/datafn/query", {
            resource: "skillVersions",
            version: 1,
            select: ["*"],
            filters: { skillId: tenantB.skillId },
            limit: 100,
          }),
        );
        expect(foreign.status).toBe(200);
        expect((await foreign.json()).result.data).toEqual([]);
      });

      it("denies generic mutations and secret-bearing resources", async () => {
        const mutation = await handle(
          request(tenantA, "/datafn/mutation", {
            resource: "skills",
            version: 1,
            operation: "merge",
            data: { id: tenantA.skillId, name: "Bypass" },
          }),
        );
        expect(mutation.status).toBe(403);

        const secret = await handle(
          request(tenantA, "/datafn/query", {
            resource: "authfnSessions",
            version: 1,
            select: ["id"],
          }),
        );
        expect([400, 403]).toContain(secret.status);
        expect(JSON.stringify(await secret.json())).not.toContain("tokenHash");
      });
    });
  },
);

